type UserThreadResource struct {
	http *HTTPClient
}

func newUserThreadResource(h *HTTPClient) *UserThreadResource {
	return &UserThreadResource{
		http: h,
	}
}

// List: List threads for a user
//
// Returns all threads visible to the specified user. The authenticated caller must
// have access to the target user's account; a 403 is returned otherwise.
// Pass one or more `agent` IDs to narrow results to threads where at least one of
// the listed agents is also a member useful for displaying every thread a user
// shares with a particular agent. Pass one or more `filter` objects to narrow
// results by thread metadata key/value pairs. Both narrowings may be combined in
// a single request.
// Results are returned as a flat array; no cursor-based pagination is applied.
// Threads are ordered with default threads first, then by most recent activity
// (newest first), each carrying a `last_activity` timestamp.
//
// user: User ID (`usr_...`) whose threads should be listed.
//
// Returns: Successful response
func (r *UserThreadResource) List(ctx context.Context, user string, params UserThreadListParams) (*UserThreadListResponse, error) {
	q := url.Values{}
	for _, item := range params.Agent {
		q.Add("agent", item)
	}
	for _, item := range params.Filter {
		q.Add("filter", queryParam(item))
	}
	return fetch[*UserThreadListResponse](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/users/" + url.PathEscape(user) + "/threads", Query: q})
}

// Create: Create a thread for a user
//
// Creates a new thread owned by the specified user. The authenticated caller must
// have access to the target user's account; a 403 is returned otherwise.
// An automatic welcome message is sent into the thread upon creation unless
// `skip_welcome_message` is set to `true`. The thread is immediately visible to
// the owning user and any members added at creation time.
//
// user: User ID (`usr_...`) whose threads should be listed.
//
// Returns: The newly created thread object.
func (r *UserThreadResource) Create(ctx context.Context, user string, input UserThreadCreateInput) (*Thread, error) {
	return fetch[*Thread](r.http, ctx, requestSpec{Method: "POST", Path: "/api/v1/users/" + url.PathEscape(user) + "/threads", Body: input})
}

type TokenResource struct {
	http *HTTPClient
}

func newTokenResource(h *HTTPClient) *TokenResource {
	return &TokenResource{
		http: h,
	}
}

// List: List personal access tokens
//
// Returns all access tokens associated with the authenticated user, including
// active and revoked tokens. Tokens are returned without their raw JWT values
// the plaintext JWT is only available at creation time.
// The caller must be the user identified by `user` and must present a
// first-party session (or a `full_access` access token).
//
// user: User ID (`usr_...`) or `me` for the authenticated user.
//
// Returns: Successful response
func (r *TokenResource) List(ctx context.Context, user string) (*TokenListResponse, error) {
	return fetch[*TokenListResponse](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/users/" + url.PathEscape(user) + "/tokens"})
}

// Create: Create a personal access token
//
// Issues a new long-lived access token for the authenticated user. The raw
// JWT is returned in the `token` field of the response exactly once and
// cannot be retrieved again store it securely immediately after creation.
// `scopes` is optional. When omitted the token receives `full_access`.
// Known catalog scopes (for example `profile`) restrict the token through
// the same `ScopeGuard` used by OAuth.
// `expires_in_days` is optional and must be one of `7`, `30`, `60`, `90`,
// or `365`. When omitted the token lasts 30 days. Each user may hold at
// most 50 active tokens; exceeding that limit returns 429.
// The caller must be the user identified by `user` and must present a
// first-party session (or a `full_access` access token). A restricted
// access token cannot mint another token.
//
// user: User ID (`usr_...`) or `me` for the authenticated user.
//
// Returns: The newly created access token. The `token` field contains the raw JWT and is present only in this response it is not stored and cannot be retrieved later.
func (r *TokenResource) Create(ctx context.Context, user string, input TokenCreateInput) (*SystemAccessToken, error) {
	return fetch[*SystemAccessToken](r.http, ctx, requestSpec{Method: "POST", Path: "/api/v1/users/" + url.PathEscape(user) + "/tokens", Body: input})
}

// Delete: Revoke a personal access token
//
// Permanently revokes the specified access token belonging to the
// authenticated user. Once revoked, the token is immediately rejected by
// all API endpoints and cannot be reinstated. The token record is retained
// and returned in the response with `revoked_at` populated.
// The caller must be the user identified by `user` and must present a
// first-party session (or a `full_access` access token). Returns 404 if
// the token does not exist or does not belong to the caller.
//
// user: User ID (`usr_...`) or `me` for the authenticated user.
// token: Access token ID (`sat_...`). Must belong to the authenticated user.
//
// Returns: The revoked access token. The `revoked_at` field is populated with the time of revocation.
func (r *TokenResource) Delete(ctx context.Context, user string, token string) (*SystemAccessToken, error) {
	return fetch[*SystemAccessToken](r.http, ctx, requestSpec{Method: "DELETE", Path: "/api/v1/users/" + url.PathEscape(user) + "/tokens/" + url.PathEscape(token)})
}

type UserResource struct {
	http    *HTTPClient
	SSHKeys *UserSSHKeyResource
	Tasks   *UserTaskResource
	Threads *UserThreadResource
	Tokens  *TokenResource
}

func newUserResource(h *HTTPClient) *UserResource {
	return &UserResource{
		http:    h,
		SSHKeys: newUserSSHKeyResource(h),
		Tasks:   newUserTaskResource(h),
		Threads: newUserThreadResource(h),
		Tokens:  newTokenResource(h),
	}
}

// Me: Retrieve the current user
//
// Returns the user associated with the authenticated session or bearer
// token. This is the canonical way to resolve "who am I?" after
// authentication.
// The response includes the user's profile, notification settings, and
// profile picture, along with the app, organization, and sandbox the
// token is scoped to and their display names enough to establish full
// session context in a single call. Unauthenticated requests return 401.
//
// Returns: The authenticated user object.
func (r *UserResource) Me(ctx context.Context, params UserMeParams) (*CurrentUser, error) {
	q := url.Values{}
	for _, item := range params.Entitlement {
		q.Add("entitlement", item)
	}
	return fetch[*CurrentUser](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/users/me", Query: q})
}

// Get: Retrieve a user by ID
//
// Returns the user identified by `user`. The authenticated user must share
// at least one team with the target user; requests for users outside any
// shared team are rejected with 403.
// A user may always retrieve their own profile with this endpoint. Use the
// `GET /users/me` endpoint as a convenience alias for retrieving the
// authenticated user without specifying an ID.
//
// user: User ID (`usr_...`) of the user to retrieve.
//
// Returns: The requested user object.
func (r *UserResource) Get(ctx context.Context, user string) (*User, error) {
	return fetch[*User](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/users/" + url.PathEscape(user)})
}

// Artifacts: List a user's artifacts
//
// Returns all artifacts owned by the specified user. Artifacts represent
// AI-generated or user-uploaded files associated with agent sessions,
// threads, or sandboxes such as images, documents, and code outputs.
// The authenticated user must be requesting their own artifacts or must
// have administrative access. Attempting to list artifacts for a user
// the caller is not authorized to access returns 403.
// Results are returned in a single page without cursor pagination. Each
// artifact in the response reflects the state of its current version,
// including a short-lived signed `file_url` for direct download.
//
// user: User ID (`usr_...`). The authenticated user must be this user or have access to their artifacts.
//
// Returns: Successful response
func (r *UserResource) Artifacts(ctx context.Context, user string) (*UserArtifactsResponse, error) {
	return fetch[*UserArtifactsResponse](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/users/" + url.PathEscape(user) + "/artifacts"})
}

// Invites: Create a user invite
//
// Creates a new invite for the authenticated user. The invite can optionally be
// scoped to a specific thread, a persona, or carry arbitrary metadata. The
// caller receives the new invite object at HTTP 201.
// The invite key is always generated server-side (192-bit URL-safe random
// string) and cannot be supplied by the caller.
// The path `:user` must match the authenticated user. If a `thread_id` is
// provided, the authenticated user must have permission to invite others to that
// thread; team threads are not supported and return an error. Supplying a
// `thread_id` that does not exist or that belongs to a different user returns
// an error. If a key collision occurs during creation the call returns a 409
// conflict simply retry to generate a new key.
//
// user: User ID (`usr_...`). Must match the authenticated user.
//
// Returns: The newly created invite object.
func (r *UserResource) Invites(ctx context.Context, user string, input UserInvitesInput) (*UserInvite, error) {
	return fetch[*UserInvite](r.http, ctx, requestSpec{Method: "POST", Path: "/api/v1/users/" + url.PathEscape(user) + "/invites", Body: input})
}

// Orgs: List organizations for a user
//
// Returns the organizations the specified user belongs to. A user can belong
// to at most one organization, so the `data` array contains either zero or one
// items.
// The authenticated viewer must have permission to inspect the target user.
// Returns an empty `data` array when the user has no organization membership.
//
// user: User ID (`usr_...`) whose organization membership you want to retrieve.
//
// Returns: Successful response
func (r *UserResource) Orgs(ctx context.Context, user string) (*UserOrgsResponse, error) {
	return fetch[*UserOrgsResponse](r.http, ctx, requestSpec{Method: "GET", Path: "/api/v1/users/" + url.PathEscape(user) + "/orgs"})
}

// Profile: Update the current user's profile
//
// Updates one or more profile fields for the authenticated user. All
// fields are optional; omit any you do not want to change.
// When `profile_picture` is supplied, the image is uploaded and replaces
// the existing picture. The previous picture is deleted after the new one
// is stored. Image upload failures return 422 without modifying other
// profile fields.
//
// user: User ID (`usr_...`) or `"me"` for the authenticated user.
//
// Returns: The user object with updated profile fields.
func (r *UserResource) Profile(ctx context.Context, user string, input UserProfileInput) (*User, error) {
	return fetch[*User](r.http, ctx, requestSpec{Method: "PUT", Path: "/api/v1/users/" + url.PathEscape(user) + "/profile", Body: input})
}
